import{_ as t,C as n,o as e,c as d,E as p,a2 as i}from"./chunks/framework.BhCQlvXS.js";const m=JSON.parse('{"title":"架构概览","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md","lastUpdated":1786592444000}'),l={name:"architecture.md"};function r(o,a,c,u,h,b){const s=n("VersionBadge");return e(),d("div",null,[p(s),a[0]||(a[0]=i(`<h1 id="架构概览" tabindex="-1">架构概览 <a class="header-anchor" href="#架构概览" aria-label="Permalink to &quot;架构概览&quot;">​</a></h1><p>本文档面向需要深入理解 Exero 内部机制的开发者。读完本文档，你将理解 Exero 的整体架构、扩展系统设计、插件宿主层、数据流和关键设计决策。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>技术</th><th>说明</th></tr></thead><tbody><tr><td>应用框架</td><td>Tauri v2</td><td>跨平台桌面应用框架，Rust 后端 + WebView2 前端</td></tr><tr><td>后端语言</td><td>Rust (stable, edition 2021)</td><td>x64，MSVC 工具链</td></tr><tr><td>前端框架</td><td>React 18 + TypeScript</td><td>Vite 构建，shadcn/ui + Radix + Tailwind CSS</td></tr><tr><td>可视化编辑器</td><td>React Flow (@xyflow/react)</td><td>拖拽连线式工作流编辑器</td></tr><tr><td>动画</td><td>framer-motion</td><td>页面切换/微交互统一动画体系（Beta9 起替代手写 CSS keyframes）</td></tr><tr><td>通知</td><td>sonner</td><td>应用内 Toast 通知</td></tr><tr><td>图表</td><td>recharts</td><td>性能页趋势折线、首页迷你图</td></tr><tr><td>数据库</td><td>SQLite (rusqlite + refinery)</td><td>WAL 模式，便携式存储</td></tr><tr><td>Lua 引擎</td><td>LuaJIT (mlua crate)</td><td>严格沙箱，10 秒超时</td></tr><tr><td>动态库加载</td><td>libloading + C ABI</td><td>运行时加载 .dll，extern &quot;C&quot; 接口</td></tr><tr><td>硬件传感器</td><td>LibreHardwareMonitorLib 子进程</td><td>GPU 使用率/温度/显存 + CPU 温度（NexBoxMonitor.exe）</td></tr><tr><td>状态管理</td><td>Zustand</td><td>轻量级状态管理</td></tr><tr><td>包管理器</td><td>pnpm</td><td>corepack 管理</td></tr></tbody></table><h2 id="整体架构" tabindex="-1">整体架构 <a class="header-anchor" href="#整体架构" aria-label="Permalink to &quot;整体架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─ Exero 主窗口 (React SPA) ──────────────────────────────────┐</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  ┌─ Sidebar ──┐  ┌─ 主内容区 ──────────────────────────────┐ │</span></span>
<span class="line"><span>│  │ 首页        │  │  页面：                                 │ │</span></span>
<span class="line"><span>│  │ 时间轴      │  │  1. 首页（任务工作流+系统状态+最近记录）│ │</span></span>
<span class="line"><span>│  │ 快捷指令    │  │  2. 时间轴（日/周四视图，校园/日常模式）│ │</span></span>
<span class="line"><span>│  │ 扩展市场    │  │  3. 快捷指令（Flow 编辑器+执行日志）    │ │</span></span>
<span class="line"><span>│  │ 性能优化    │  │  4. 性能优化（四卡片+进程管理）         │ │</span></span>
<span class="line"><span>│  │ 设置        │  │  5. 设置（外观/通用/扩展/插件/更新/…） │ │</span></span>
<span class="line"><span>│  │ ─────────  │  │  6. 更新历史（二级页面）                │ │</span></span>
<span class="line"><span>│  │ 📌 插件入口 │  └────────────────────────────────────────┘ │</span></span>
<span class="line"><span>│  └────────────┘                                              │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  ┌─ 扩展系统 ──────────────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │  ActionExecutorRegistry (动作执行器注册表)               │ │</span></span>
<span class="line"><span>│  │  ├── 内置 20 种 ActionType                               │ │</span></span>
<span class="line"><span>│  │  ├── Lua 执行器 (LuaJIT 沙箱)                            │ │</span></span>
<span class="line"><span>│  │  └── Rust 执行器 (libloading .dll + C ABI)              │ │</span></span>
<span class="line"><span>│  │                                                          │ │</span></span>
<span class="line"><span>│  │  ExtensionPackRegistry (扩展包注册表)                    │ │</span></span>
<span class="line"><span>│  │  ├── builtin: &lt;exe_dir&gt;/data/action-packs/              │ │</span></span>
<span class="line"><span>│  │  ├── user: %APPDATA%/Exero/action-packs/                │ │</span></span>
<span class="line"><span>│  │  └── custom: settings extension_pack.user_dir           │ │</span></span>
<span class="line"><span>│  │                                                          │ │</span></span>
<span class="line"><span>│  │  RustLibraryRegistry (Rust .dll 注册表)                  │ │</span></span>
<span class="line"><span>│  │  └── LoadLibrary + exero_pack_init + exero_execute_action│ │</span></span>
<span class="line"><span>│  └──────────────────────────────────────────────────────────┘ │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  ┌─ 插件宿主层 PluginHostLayer（Beta9 常驻） ──────────────┐ │</span></span>
<span class="line"><span>│  │  每个存活插件一个 iframe（plugin.localhost 协议）        │ │</span></span>
<span class="line"><span>│  │  ├── 活跃插件 absolute 覆盖主内容区                      │ │</span></span>
<span class="line"><span>│  │  ├── 非活跃插件 display:none 保活（音频/定时器继续）     │ │</span></span>
<span class="line"><span>│  │  ├── 桥接脚本注入 (window.exero.invoke/storage)          │ │</span></span>
<span class="line"><span>│  │  └── postMessage ↔ execute_plugin_action → .dll          │ │</span></span>
<span class="line"><span>│  └──────────────────────────────────────────────────────────┘ │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>         ▼</span></span>
<span class="line"><span>┌─ Rust 后端 (Tauri Commands) ─────────────────────────────────┐</span></span>
<span class="line"><span>│  数据库层 (rusqlite + refinery)                              │</span></span>
<span class="line"><span>│  ├── 流程数据 5 表 (flows/actions/triggers/logs/settings)   │</span></span>
<span class="line"><span>│  └── 课程数据 5 表 (semesters/periods/templates/courses/...) │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  触发器调度器 (tokio)                                        │</span></span>
<span class="line"><span>│  ├── Cron 定时触发（时间触发积木生成）                       │</span></span>
<span class="line"><span>│  ├── 课表触发 CourseStart（课前N分钟/课中/课后）             │</span></span>
<span class="line"><span>│  ├── 系统事件触发 (开机/关机/USB/网络/进程)                  │</span></span>
<span class="line"><span>│  └── 手动触发 (首页/托盘)                                    │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  动作执行引擎                                                │</span></span>
<span class="line"><span>│  ├── 顺序执行 + 条件分支 + 循环 + 变量传递                   │</span></span>
<span class="line"><span>│  ├── 容错策略 (继续/停止/回滚/通知)                          │</span></span>
<span class="line"><span>│  └── 动作超时 (Lua 默认 10s)                                 │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  传感器子系统 sensors/（Beta9）                              │</span></span>
<span class="line"><span>│  ├── bridge.rs: NexBoxMonitor.exe 子进程管理（stdin/stdout） │</span></span>
<span class="line"><span>│  └── reader.rs: GPU/CPU 温度 JSON 轮询读取                   │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  窗口效果                                                    │</span></span>
<span class="line"><span>│  ├── Effect::Acrylic 系统级 DWM 模糊（Win11 DWMSB/Win10 降级）│</span></span>
<span class="line"><span>│  └── DWMWCP_ROUND 物理圆角 + WebView2 透明背景               │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="扩展系统架构" tabindex="-1">扩展系统架构 <a class="header-anchor" href="#扩展系统架构" aria-label="Permalink to &quot;扩展系统架构&quot;">​</a></h2><h3 id="两种扩展形态对比" tabindex="-1">两种扩展形态对比 <a class="header-anchor" href="#两种扩展形态对比" aria-label="Permalink to &quot;两种扩展形态对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>动作包 (Action Pack)</th><th>插件 (Plugin)</th></tr></thead><tbody><tr><td><strong>pack_type</strong></td><td><code>&quot;action&quot;</code></td><td><code>&quot;plugin&quot;</code></td></tr><tr><td><strong>后端语言</strong></td><td>Rust (.dll) 或 Lua (.lua)</td><td>必须 Rust (.dll)</td></tr><tr><td><strong>UI 页面</strong></td><td>无</td><td>有 (iframe)</td></tr><tr><td><strong>侧边栏入口</strong></td><td>无</td><td>有（独占）</td></tr><tr><td><strong>Flow 积木</strong></td><td>有</td><td>可选（附带动作）</td></tr><tr><td><strong>后台持久运行</strong></td><td>无</td><td>有（默认开启，可配置）</td></tr><tr><td><strong>适用场景</strong></td><td>纯动作扩展</td><td>完整功能页面</td></tr></tbody></table><h3 id="触发与执行流程" tabindex="-1">触发与执行流程 <a class="header-anchor" href="#触发与执行流程" aria-label="Permalink to &quot;触发与执行流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时间触发积木（重复规则/课表触发）→ 前端生成 Cron / CourseStart 配置</span></span>
<span class="line"><span>  → triggers 表（set_triggers）</span></span>
<span class="line"><span>  → Trigger 调度器（Cron 循环 / 课表 next_fire_time 计算）</span></span>
<span class="line"><span>  → 到点加载 AutomationFlow</span></span>
<span class="line"><span>  → 按 actions 顺序执行</span></span>
<span class="line"><span>    → ActionExecutorRegistry 查找执行器</span></span>
<span class="line"><span>      ├── 内置 ActionType (LaunchProgram/SetVolume/Shutdown...)</span></span>
<span class="line"><span>      ├── Lua 执行器 (LuaJIT 沙箱执行 .lua)</span></span>
<span class="line"><span>      └── Rust 执行器 (libloading 调用 .dll 导出函数)</span></span>
<span class="line"><span>    → 返回 ActionResult (output + status)</span></span>
<span class="line"><span>    → 容错策略判断 (继续/停止/回滚/通知)</span></span>
<span class="line"><span>  → 写入 execution_logs</span></span></code></pre></div><p>时间触发积木（Beta9）在 Flow 编辑器中作为「控制流」分组的起点节点，前端提供重复规则选择器（每天/每周/每 N 天/指定日期）和课表触发配置（选课程 + 课前 N 分钟/课中/课后），由前端转换为 Cron 表达式或 CourseStart 参数传给后端——用户无需接触 Cron 语法。</p><h3 id="插件宿主层与持久运行-beta9" tabindex="-1">插件宿主层与持久运行（Beta9） <a class="header-anchor" href="#插件宿主层与持久运行-beta9" aria-label="Permalink to &quot;插件宿主层与持久运行（Beta9）&quot;">​</a></h3><p>插件 iframe 不再随页面切换卸载，而是由常驻宿主层 <code>PluginHostLayer</code> 管理（类似 Chrome 扩展的后台页）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户点击侧边栏插件入口</span></span>
<span class="line"><span>  → PluginActivator 挂载，向 pluginHost store 注册插件</span></span>
<span class="line"><span>  → PluginHostLayer 渲染该插件的 iframe（首次加载）</span></span>
<span class="line"><span>    → iframe src=&quot;http://plugin.localhost/{pack_id}/{entry}&quot;</span></span>
<span class="line"><span>    → Tauri 自定义协议读取 HTML + 注入桥接脚本</span></span>
<span class="line"><span>  → 该 iframe absolute 覆盖主内容区展示</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用户切换到其他页面</span></span>
<span class="line"><span>  → iframe 改为 display:none（不卸载、src 不变）</span></span>
<span class="line"><span>  → 音频播放 / 定时器 / 后台任务继续运行</span></span>
<span class="line"><span>  → 再次进入插件页时瞬时恢复（无重新加载）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用户离开插件页（keep_alive 开启，默认）</span></span>
<span class="line"><span>  → 插件继续存活，占用保持</span></span>
<span class="line"><span>用户离开插件页（keep_alive 关闭）</span></span>
<span class="line"><span>  → iframe 销毁，下次进入重新加载</span></span></code></pre></div><p>keep_alive 按插件独立配置，持久化在 settings 表（键 <code>plugin.keep_alive.{pack_id}</code>）。用户可在「设置 → 插件」切换开关、清理插件缓存（宿主存储数据）或强制停止插件。</p><h3 id="插件-ui-桥接流程" tabindex="-1">插件 UI 桥接流程 <a class="header-anchor" href="#插件-ui-桥接流程" aria-label="Permalink to &quot;插件 UI 桥接流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户在插件页面调用 window.exero.invoke(actionId, params)</span></span>
<span class="line"><span>  → 桥接脚本 postMessage({ type: &#39;exero-invoke&#39;, id, actionId, params })</span></span>
<span class="line"><span>  → PluginHostLayer 监听 message 事件</span></span>
<span class="line"><span>  → 调用 Tauri 命令 execute_plugin_action(pack_id, action_id, params)</span></span>
<span class="line"><span>  → RustLibraryRegistry::execute (C ABI 调用 .dll)</span></span>
<span class="line"><span>  → postMessage({ type: &#39;exero-result&#39;, id, result|error })</span></span>
<span class="line"><span>  → 桥接脚本 resolve Promise</span></span></code></pre></div><p>存储 API（<code>window.exero.storage.*</code>）同链路，落到 <code>%APPDATA%/Exero/plugin-data/{pack_id}.json</code>，按插件隔离。</p><h3 id="rust-dll-c-abi-接口" tabindex="-1">Rust .dll C ABI 接口 <a class="header-anchor" href="#rust-dll-c-abi-接口" aria-label="Permalink to &quot;Rust .dll C ABI 接口&quot;">​</a></h3><p>SDK 的 <code>declare_actions!</code> 宏自动生成 4 个导出函数：</p><table tabindex="0"><thead><tr><th>函数</th><th>签名</th><th>说明</th></tr></thead><tbody><tr><td><code>exero_pack_init</code></td><td><code>() -&gt; i32</code></td><td>加载时调用，返回 0 表示成功</td></tr><tr><td><code>exero_pack_cleanup</code></td><td><code>() -&gt; void</code></td><td>卸载时调用</td></tr><tr><td><code>exero_execute_action</code></td><td><code>(action_id, params_json) -&gt; *const c_char</code></td><td>执行动作，返回 JSON 字符串</td></tr><tr><td><code>exero_last_error</code></td><td><code>() -&gt; *const c_char</code></td><td>获取最近一次错误信息</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">安全模型</p><p>.dll 加载无沙箱隔离，可完全访问系统（与 Lua 宽松沙箱同级风险）。用户自担风险安装第三方插件。.dll 必须编译为 <code>x86_64-pc-windows-msvc</code> 目标。</p></div><h2 id="窗口效果体系-beta9" tabindex="-1">窗口效果体系（Beta9） <a class="header-anchor" href="#窗口效果体系-beta9" aria-label="Permalink to &quot;窗口效果体系（Beta9）&quot;">​</a></h2><p>主窗口视觉采用「系统级模糊 + CSS 质感层」分工：</p><table tabindex="0"><thead><tr><th>层</th><th>实现</th><th>说明</th></tr></thead><tbody><tr><td>模糊层</td><td>Tauri <code>Effect::Acrylic</code>（Rust 侧 <code>set_effects</code>）</td><td>系统级 DWM 模糊，模糊的就是桌面壁纸本身。Win11 22H2+ 走 DWMSB 系统 backdrop，Win10/旧 Win11 自动降级 ACCENT</td></tr><tr><td>圆角</td><td>DWMWCP_ROUND 物理圆角 + CSS clip-path 双保险</td><td>DWM 沿窗口圆角裁剪系统亚克力；CSS 裁剪 WebView 内容</td></tr><tr><td>着色层</td><td>CSS 半透明 <code>--alpha-*</code> 变量（<code>[data-acrylic=&quot;true&quot;]</code>）</td><td>背景 0.88 / 侧边栏 0.85 / 卡片 0.80 分层透明度</td></tr><tr><td>噪点/光影</td><td>SVG feTurbulence 纹理 + inset box-shadow</td><td>亚克力质感</td></tr><tr><td>开关</td><td>settings <code>theme.acrylic_enabled</code></td><td>低性能机器可关闭，回退纯色背景</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">为什么不用 CSS backdrop-filter 模糊壁纸</p><p>Chromium 的 backdrop image 只包含同一 WebView 渲染树内元素背后的内容。窗口全透明后元素&quot;背后&quot;是空的，<code>blur()</code> 模糊的是&quot;空气&quot;——物理上无法触及 DWM 合成器中的桌面壁纸。弹层（popover/dropdown）例外：其背后是渲染树内的实际页面内容，<code>backdrop-filter</code> 有效。</p></div><p>外观定制（密度/字体/图标风格/LiquidGlass）通过 settings 表的 <code>theme.density</code>、<code>theme.font_family</code>、<code>theme.font_size</code>、<code>theme.icon_style</code>、<code>theme.liquid_glass</code> 等键持久化，由前端 <code>applyAppearance</code> 写入 html data 属性驱动 CSS。</p><h2 id="传感器子系统-beta9" tabindex="-1">传感器子系统（Beta9） <a class="header-anchor" href="#传感器子系统-beta9" aria-label="Permalink to &quot;传感器子系统（Beta9）&quot;">​</a></h2><p>性能页 GPU 数据来自 LibreHardwareMonitorLib 子进程方案：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src-tauri/resources/monitor/          # 打包资源（.NET 子进程 + 依赖 DLL）</span></span>
<span class="line"><span>├── NexBoxMonitor.exe                 # C# 子进程，调 LibreHardwareMonitorLib.dll</span></span>
<span class="line"><span>└── *.dll                             # LHM + .NET 依赖</span></span>
<span class="line"><span></span></span>
<span class="line"><span>src-tauri/src/sensors/</span></span>
<span class="line"><span>├── bridge.rs                         # 子进程 spawn/stdin/stdout JSON 通信管理</span></span>
<span class="line"><span>└── reader.rs                         # 读取 API（GPU 使用率/温度/显存、CPU 温度）</span></span></code></pre></div><ul><li>覆盖 NVIDIA / AMD / Intel GPU；子进程独立于主进程，崩溃不影响主程序</li><li>依赖 .NET Framework 4.8+（Win10/11 默认已装）</li><li>找不到子进程或读取失败时静默降级，性能页 GPU 卡片显示占位提示</li></ul><h2 id="数据库架构" tabindex="-1">数据库架构 <a class="header-anchor" href="#数据库架构" aria-label="Permalink to &quot;数据库架构&quot;">​</a></h2><h3 id="流程数据-5-表" tabindex="-1">流程数据（5 表） <a class="header-anchor" href="#流程数据-5-表" aria-label="Permalink to &quot;流程数据（5 表）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表</th><th>用途</th><th>关键字段</th></tr></thead><tbody><tr><td><code>automation_flows</code></td><td>快捷指令</td><td>id, name, icon, enabled</td></tr><tr><td><code>actions</code></td><td>动作块</td><td>id, flow_id, type, params, order, parent_id, fault_strategy</td></tr><tr><td><code>triggers</code></td><td>触发器</td><td>id, flow_id, type (Cron/CourseStart/...), params, enabled</td></tr><tr><td><code>execution_logs</code></td><td>执行日志</td><td>id, flow_id, action_id, status, started_at, finished_at, error</td></tr><tr><td><code>settings</code></td><td>设置</td><td>key, value, type</td></tr></tbody></table><h3 id="课程数据-5-表-与流程数据解耦" tabindex="-1">课程数据（5 表，与流程数据解耦） <a class="header-anchor" href="#课程数据-5-表-与流程数据解耦" aria-label="Permalink to &quot;课程数据（5 表，与流程数据解耦）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表</th><th>用途</th></tr></thead><tbody><tr><td><code>semesters</code></td><td>学期定义</td></tr><tr><td><code>class_periods</code></td><td>节次时间表</td></tr><tr><td><code>weekly_templates</code></td><td>周课表模板（普通周/特殊周）</td></tr><tr><td><code>courses</code></td><td>课程实体（归属周模板，含 week_pattern 单双周）</td></tr><tr><td><code>schedule_overrides</code></td><td>临时调课记录（单次生效）</td></tr></tbody></table><p>课表触发（CourseStart）基于这 5 张表计算下一次触发时间：按星期 + 周次模式（all/odd/even/指定周）过滤课程，结合触发时机（Before 减 N 分钟 / During 开始时刻 / After 结束时刻）得出本地时间并转 UTC 调度。</p><h2 id="扩展包加载策略" tabindex="-1">扩展包加载策略 <a class="header-anchor" href="#扩展包加载策略" aria-label="Permalink to &quot;扩展包加载策略&quot;">​</a></h2><h3 id="三目录扫描-优先级从高到低" tabindex="-1">三目录扫描（优先级从高到低） <a class="header-anchor" href="#三目录扫描-优先级从高到低" aria-label="Permalink to &quot;三目录扫描（优先级从高到低）&quot;">​</a></h3><ol><li><strong>builtin</strong>：<code>&lt;exe_dir&gt;/data/action-packs/</code>（只读）</li><li><strong>user</strong>：<code>%APPDATA%/Exero/action-packs/</code>（可写）</li><li><strong>custom</strong>：settings <code>extension_pack.user_dir</code>（可选）</li></ol><p>同名扩展包先加载的优先（builtin &gt; user &gt; custom）。</p><h3 id="市场分发" tabindex="-1">市场分发 <a class="header-anchor" href="#市场分发" aria-label="Permalink to &quot;市场分发&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Market/</span></span>
<span class="line"><span>├── market-index.json          # 元数据索引（list_market_packs 只下载此文件）</span></span>
<span class="line"><span>├── action-packs/              # 动作包 .exero-pack</span></span>
<span class="line"><span>└── plugins/                   # 插件 .exero-pack</span></span></code></pre></div><p>网络后备（三级）：GitHub 直连 → Gitee 备源（GitHub Actions 自动同步）→ ghproxy 镜像 → 离线模式（仅已安装）。应用更新下载走同样的三级降级。</p><h2 id="关键设计决策摘要" tabindex="-1">关键设计决策摘要 <a class="header-anchor" href="#关键设计决策摘要" aria-label="Permalink to &quot;关键设计决策摘要&quot;">​</a></h2><table tabindex="0"><thead><tr><th>决策</th><th>原因</th></tr></thead><tbody><tr><td>C ABI 而非 Rust ABI</td><td>Rust 自身 ABI 不稳定，C ABI 保证兼容性</td></tr><tr><td>iframe + postMessage</td><td>天然隔离，插件崩溃不影响主程序</td></tr><tr><td>不允许 <code>allow-same-origin</code></td><td>防止插件访问 Exero 主窗口 DOM</td></tr><tr><td>常驻 iframe 宿主层（Beta9）</td><td>类 Chrome 扩展的持久运行：切页不卸载，音频/定时器继续</td></tr><tr><td>系统级 Acrylic 而非 CSS 模糊</td><td>CSS backdrop-filter 物理上模糊不到桌面壁纸（渲染树限制）</td></tr><tr><td>LuaJIT 而非标准 Lua</td><td>性能最优，对自动化脚本几乎无损耗</td></tr><tr><td>market-index.json 索引</td><td>只下载 1 个文件而非逐个下载 zip，减少网络请求</td></tr><tr><td>三目录扫描</td><td>builtin（内置）+ user（用户安装）+ custom（自定义路径）</td></tr><tr><td>courses 表同时存 period_index 和 time</td><td>拖拽时两个字段互斥更新，兼顾课表定位和精确时间</td></tr><tr><td>前端生成 Cron 而非用户填写</td><td>时间触发积木用可视化选择器，杜绝用户手写错误表达式</td></tr><tr><td>LHM 子进程而非集成</td><td>.NET 库无法直接进 Rust，子进程隔离且崩溃可降级</td></tr></tbody></table><blockquote><p>完整的内部设计 SPEC 属于内部开发文档，不随文档发布。本套文档已涵盖开发者所需全部知识。</p></blockquote>`,48))])}const _=t(l,[["render",r]]);export{m as __pageData,_ as default};
